mapper.select:
select A.*,
       U.nickname as publisherName, U.username,
       R.nickname as runnerName,
       T.title, T.cover, T.pickup_address, T.delivery_address
from b_order as A
         left join b_user as U on (A.publisher_id = U.id)
         left join b_user as R on (A.runner_id = R.id)
         left join b_task as T on (A.task_id = T.id)
where 2>1

    and A.publisher_id = #{userId}


    and A.runner_id = #{runnerId}


    and A.status = #{status}

order by A.order_time desc;
